  'tut.app-computo--formulario.titulo': 'Das Formelbuch',
  'tut.app-computo--formulario.resumen':
    'Das Formelbuch ist dein eigenes Buch mit Formeln. Mathematik, Physik und Chemie sind schon enthalten, aber sie sind kein eigener Katalog: Es sind deine Formeln, und du bearbeitest, verschiebst oder löschst sie genau wie die, die du selbst schreibst.',
