  'ideas.tipo.tier': 'Rangliste',
  'ideas.tipoDesc.linea': 'Meilensteine der Reihe nach auf einer Linie, vom ersten bis zum letzten.',
  'ideas.tipoDesc.ciclo': 'Phasen, die sich im Kreis wiederholen und von vorn beginnen.',
